INSERT INTO refinery_units (name, code, description, throughput_capacity, status) VALUES ('Crude Distillation Unit', 'CDU', 'Separates crude oil into fractions based on boiling points.', 100000.0, 'Active');
INSERT INTO refinery_units (name, code, description, throughput_capacity, status) VALUES ('Vacuum Distillation Unit', 'VDU', 'Processes heavy residue from CDU under vacuum to extract gas oils.', 45000.0, 'Active');
INSERT INTO refinery_units (name, code, description, throughput_capacity, status) VALUES ('Fluid Catalytic Cracking Unit', 'FCC', 'Converts heavy gas oils from VDU into high-value gasoline and LPG.', 35000.0, 'Active');
INSERT INTO refinery_units (name, code, description, throughput_capacity, status) VALUES ('Hydrotreater Unit', 'Hydrotreater', 'Removes sulfur and impurities from fuel fractions using hydrogen.', 25000.0, 'Active');
INSERT INTO refinery_units (name, code, description, throughput_capacity, status) VALUES ('Storage & Logistics Terminal', 'Storage Terminal', 'Manages crude feedstocks and refined product inventory tanks.', 1000000.0, 'Active');
