INSERT INTO scenarios (name, type, description) VALUES ('FCC Shutdown', 'FCC_SHUTDOWN', 'Simulate complete catalytic cracker outage. Evaluates downstream storage backing up, gasoline yield drop, and overall plant risk.');
INSERT INTO scenarios (name, type, description) VALUES ('Throughput Increase (+10%)', 'THROUGHPUT_INCREASE', 'Test a refinery-wide 10% increase in crude throughput to identify processing bottlenecks in the hydrotreater and other units.');
INSERT INTO scenarios (name, type, description) VALUES ('Maintenance Delay', 'MAINTENANCE_DELAY', 'Assess the impact of delaying scheduled inspection/maintenance on the CDU. Raises risk profiles significantly.');
INSERT INTO scenarios (name, type, description) VALUES ('Energy Reduction (-20%)', 'ENERGY_REDUCTION', 'Evaluate operations under a 20% grid electricity supply constraint, forcing units to run at reduced rates.');
INSERT INTO scenarios (name, type, description) VALUES ('Demand Increase', 'DEMAND_INCREASE', 'Push processing units to maximum capacity to meet high market demand, highlighting system stress.');
